/// A Laguerre‐series representation:
/// - `coefficients` holds the series coefficients in order,
/// - `domain` is the input interval,
/// - `window` is the output interval.
#[derive(Debug, Clone, PartialEq)]
pub struct Laguerre {
    pub coefficients: Vec<f32>,
    pub domain: (f32, f32),
    pub window: (f32, f32),
}

/// Constructs a Laguerre series with the given coefficients,
/// and sets both domain and window to [0.0, 1.0].
pub fn make_laguerre(coefficients: Vec<f32>) -> Laguerre {
    Laguerre {
        coefficients,
        domain: (0.0, 1.0),
        window: (0.0, 1.0),
    }
}

